let packageBusy=false,lastPackageResult=null;
function showPackageDialog(){if(packageBusy){notify('正在打包，请等待完成');return}dialog('打包 Windows 游戏',`<div class="field"><label>成品名称</label><input name="name" value="${esc(project.title)}" maxlength="80" required></div><div class="field"><label>打包格式</label><select name="format"><option value="single">单文件 EXE（推荐）</option><option value="folder">便携文件夹</option></select></div><p>游戏将包含当前工程的全部剧情和素材，并保留立绘差分、CG、场景背景、特效及存读档。打包后选择输出位置，无需安装制作工作台即可运行。</p><p class="field-note">单文件 EXE 首次启动会自动准备运行文件。打包使用当前编辑内容，不会覆盖制作工程。</p>`,'选择位置并打包',f=>{const snapshot=structuredClone(project);snapshot.title=f.get('name').trim();setTimeout(()=>startGamePackage(snapshot,f.get('format')),0)})}
function packageProgressDialog(){const modal=$('#modal');$('#modalContent').innerHTML='<h2>正在打包游戏</h2><progress id="packProgress" max="100" value="0" style="width:100%;height:12px"></progress><p id="packStatus" style="margin-top:15px">准备打包…</p><p class="field-note">打包期间请保持工作台打开。可以在后台继续编辑，成品将使用开始打包时的工程内容。</p><div class="actions"><button class="btn" data-action="package-background">后台打包</button></div>';modal.showModal()}
function packageResultDialog(){const r=lastPackageResult;if(!r)return;$('#modalContent').innerHTML=`<h2>游戏打包完成</h2><p>${esc(r.title)}</p><p class="field-note">${r.scenes} 个章节 · ${r.blocks} 个剧情块 · ${r.assets} 项素材 · ${(r.bytes/1024/1024).toFixed(1)} MB</p><p class="field-note">工程快照 ${esc(r.sourceHash?.slice(0,12)||'—')}</p><p class="package-output">${esc(r.executable)}</p><p>${r.format==='single'?'可直接复制和分发此 EXE，首次运行会自动准备游戏文件。':'请完整复制便携版文件夹，双击其中的 GamePlayer.exe 运行。'}</p><div class="actions"><button class="btn" data-action="close-modal">关闭</button><button class="btn" data-action="open-export-output" data-id="report">查看打包检查</button><button class="btn" data-action="open-package-folder">打开成品文件夹</button><button class="btn primary" data-action="open-export-output" data-id="executable">运行游戏 EXE</button></div>`;if(!$('#modal').open)$('#modal').showModal()}
async function startGamePackage(snapshot,format){try{validateProject(snapshot);packageBusy=true;draw();packageProgressDialog();const result=await window.desktop.packageGame({project:snapshot,format});packageBusy=false;if(result.canceled){if($('#packProgress'))$('#modal').close();draw();notify('已取消打包');return}lastPackageResult=result;const showing=$('#modal').open&&$('#packProgress');draw();if(showing)packageResultDialog();else notify('游戏已打包，可点击「打包成品」查看')}catch(e){packageBusy=false;if($('#packProgress'))$('#modal').close();draw();notify('打包失败：'+e.message)}}
const packageDraw=draw;
draw=function(){packageDraw();$('.top-actions')?.insertAdjacentHTML('beforeend',`<button class="btn primary" data-action="package-game" ${packageBusy?'disabled':''}>${ic('download')} ${packageBusy?'正在打包…':'打包 EXE'}</button>${lastPackageResult?'<button class="btn small" data-action="package-result">打包成品</button>':''}`)};
document.addEventListener('click',e=>{const action=e.target.closest('[data-action]')?.dataset.action;if(!['package-game','package-background','package-result','open-package-folder','open-export-output'].includes(action))return;e.preventDefault();e.stopImmediatePropagation();if(action==='package-game')showPackageDialog();if(action==='package-result')packageResultDialog();if(action==='open-export-output')window.desktop.openExportOutput(e.target.closest('[data-action]').dataset.id).catch(error=>notify(error.message));if(action==='package-background')$('#modal').close();if(action==='open-package-folder')window.desktop.openPackageFolder().catch(()=>notify('无法打开成品文件夹'))},true);
window.desktop?.onPackageProgress(progress=>{const bar=$('#packProgress'),label=$('#packStatus');if(bar)bar.value=progress.percent;if(label)label.textContent=progress.message+' · '+progress.percent+'%'});
draw();

function showHtmlExportResult(file) {
  $('#modalContent').innerHTML = `<h2>离线试玩已导出</h2><p class="package-output">${esc(file)}</p>
    <div class="actions"><button class="btn" data-action="close-modal">关闭</button>
    <button class="btn primary" data-action="open-export-output" data-id="preview">打开 HTML 试玩</button></div>`;
  if (!$('#modal').open) $('#modal').showModal();
}
